// rate_limit = 1000 MB/s = 256000 pages/s (4 KiB pages)
ref_cand = rate_limit * 60000 / 1000   // per 60 s window
unit_th  = 1000 * 2 / 16              // 125 ms
th = 1000                              // start at default
for each 60 s window:
    diff = candidates seen in window
    if diff > ref_cand * 11 / 10:
        th = max(th - unit_th, unit_th)    // too many: be stricter
    elif diff < ref_cand * 9 / 10:
        th = min(th + unit_th, 2 * 1000)   // too few: be looser
    // otherwise keep th
